public String twoArraysBrute(int k, int[] A, int[] B) {
    Integer[] b = new Integer[B.length];
    for (int i = 0; i < B.length; i++) b[i] = B[i];
    return permute(A, b, 0, k) ? "YES" : "NO";
}

private boolean permute(int[] A, Integer[] b, int start, int k) {
    if (start == b.length) {
        for (int i = 0; i < A.length; i++) if (A[i] + b[i] < k) return false;
        return true;
    }
    for (int i = start; i < b.length; i++) {
        Integer t = b[start]; b[start] = b[i]; b[i] = t;
        if (permute(A, b, start + 1, k)) return true;
        t = b[start]; b[start] = b[i]; b[i] = t;
    }
    return false;
}

