public String twoArrays(int k, int[] A, int[] B) {
    int n = A.length;
    Integer[] a = new Integer[n];
    Integer[] b = new Integer[n];
    for (int i = 0; i < n; i++) { a[i] = A[i]; b[i] = B[i]; }
    Arrays.sort(a);
    Arrays.sort(b, Comparator.reverseOrder());
    for (int i = 0; i < n; i++) {
        if ((long) a[i] + b[i] < k) return "NO";
    }
    return "YES";
}

